import { ImageResponse } from "next/og";

// Official artwork (outlined SVG, generated by brand/make_logo.py), rendered to PNG at build time.
export const alt = "TensorPhysics: make reality predictable.";
export const size = { width: 1200, height: 630 };
export const contentType = "image/png";

const SVG = "data:image/svg+xml;base64,";

export default function Image() {
  return new ImageResponse(<img src={SVG} width={1200} height={630} alt="" />, size);
}
